def solve(grid):
    """
    Transform the input grid by replacing the 5's in the longest vertical line
    with 1 and the 5's in the shortest vertical line with 2. All other cells
    become 0.
    """
    if not grid:
        return grid

    n = len(grid)
    m = len(grid[0])

    # Count 5's in each column
    col_count = [0] * m
    for j in range(m):
        cnt = 0
        for i in range(n):
            if grid[i][j] == 5:
                cnt += 1
        col_count[j] = cnt

    # Consider only columns that contain at least one 5
    nonzero_cols = [j for j in range(m) if col_count[j] > 0]
    if not nonzero_cols:
        # No 5's present; return a copy of the original grid (all zeros)
        return [row[:] for row in grid]

    # Column with the most 5's -> marked with 1
    max_col = max(nonzero_cols, key=lambda j: col_count[j])
    # Column with the fewest 5's -> marked with 2
    min_col = min(nonzero_cols, key=lambda j: col_count[j])

    # Build the output grid
    out = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            val = grid[i][j]
            if val == 5:
                if j == max_col:
                    out[i][j] = 1
                elif j == min_col:
                    out[i][j] = 2
                else:
                    out[i][j] = 0
            else:
                out[i][j] = val  # keep original (typically 0)
    return out

